    76|.mh::before{content:'';position:absolute;inset:0;background:var(--modal-hdr);border-radius:var(--r) var(--r) 0 0}
    77|.mh>*{position:relative;z-index:1}
    78|.mh h2{font-size:1.35rem;color:#f0e8ff}
    79|.mh .tj{font-size:0.75rem;color:var(--muted)}
