{"content": "    80|.mc{position:relative;z-index:2;background:none;border:1px solid rgba(255,255,255,0.08);font-size:1.3rem;cursor:pointer;color:rgba(210,195,235,0.4);padding:2px 10px;border-radius:50%}
    81|.mc:hover{color:var(--pink);border-color:var(--pink)}
    82|.mb{padding:18px 22px}
    83|.mb section{margin-bottom:16px}
    84|.mb section h3{font-size:1rem;background:linear-gradient(135deg,#ff6b9d,#c471f5);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid rgba(255,107,157,0.1)}
    85|.mi{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
    86|.mi-item{padding:4px 12px;border-radius:14px;font-size:0.74rem;background:rgba(255,107,157,0.04);border:1px solid rgba(255,107,157,0.05)}
    87|.mi-item strong{color:var(--pink)}
    88|.ch{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
    89|.ch-card{display:flex;gap:10px;background:var(--ch-card-bg);padding:10px;border-radius:8px;border:1px solid rgba(255,107,157,0.04);transition:all 0.2s}
    90|.ch-card:hover{background:rgba(196,113,245,0.06)}
    91|.ch-av{width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,#c471f5,#ff6b9d);display:flex;align-items:center;justify-content:center;font-size:1.3rem;flex-shrink:0}
    92|.ch-info h4{font-size:0.83rem;color:#f0e8ff}
    93|.ch-info .cv{font-size:0.66rem;color:var(--muted)}
    94|.ch-info p{font-size:0.72rem;color:var(--muted);line-height:1.3}
    95|.cg{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px}
    96|.cg-i{border-radius:8px;overflow:hidden;border:1.5px solid rgba(126,200,227,0.08);aspect-ratio:16/10;transition:all 0.3s;cursor:pointer}
    97|.cg-i img{width:100%;height:100%;object-fit:cover}
    98|.cg-i:hover{transform:scale(1.04);border-color:rgba(196,113,245,0.35);box-shadow:0 3px 10px rgba(196,113,245,0.12)}
    99|.cg-i .ph{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:2rem;background:linear-gradient(135deg,rgba(196,113,245,0.08),rgba(126,200,227,0.08))}
   100|.rl{display:flex;flex-wrap:wrap;gap:6px}
   101|.rlink{display:inline-flex;align-items:center;gap:3px;padding:7px 13px;border-radius:18px;text-decoration:none;font-size:0.78rem;font-weight:600;transition:all 0.3s}
   102|.ro{background:linear-gradient(135deg,#ff6b9d,#f06292);color:#fff}
   103|.ro:hover{transform:translateY(-2px);box-shadow:0 3px 10px rgba(255,107,157,0.25)}
