   105|.rv:hover{background:rgba(126,200,227,0.22)}
   106|.rs{background:#1b2838;color:#fff}
   107|.rst{background:rgba(255,211,0,0.08);color:#ffd54f;border:1px solid rgba(255,211,0,0.12)}
   108|.rs-title{text-align:center;margin:40px 0 18px;font-size:1.3rem;background:linear-gradient(135deg,#ff6b9d,#c471f5,#7ec8e3);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-weight:900}
   109|.rs-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;padding:0 20px 40px}
   110|.rs-card{background:rgba(30,15,50,0.85);backdrop-filter:blur(8px);border:2px solid rgba(196,113,245,0.25);border-radius:var(--r);padding:16px;transition:all 0.3s;text-decoration:none;color:#e0d8f8;display:block;cursor:pointer;position:relative;z-index:10}
   111|.rs-card:active{transform:scale(0.97);background:rgba(196,113,245,0.15)}
   112|.rs-card::after{content:'🔗 点击访问';position:absolute;top:12px;right:14px;font-size:0.65rem;color:#c471f5;opacity:0.7}
   113|.rs-card:hover,.rs-card:active{border-color:#c471f5;box-shadow:0 4px 16px rgba(196,113,245,0.3);background:rgba(40,20,60,0.9)}
   114|.rs-card .rsi{font-size:1.8rem;margin-bottom:4px}
   115|.rs-card h4{font-size:0.95rem;color:#f8f0ff;margin-bottom:2px}
